// План specs/invoices.md 1.3 (кейс .qa/tests/invoices/IN-02). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: счёт «QA-AUTO inv-cust #1a4863 …» (TTP Customer) с позицией «QA-AUTO inv-cust-line …»; в конце — Actions → Delete.
import { test, expect } from '../../fixtures';
import { CLIENT, ROLE, addManualItem, customerAlert, invoiceNameRow, invoiceNumber, openNewInvoiceForm, pickCustomer, removeDocumentAt, stamp } from './invoice-helpers';

test.describe('Счета — New Invoice без клиента (#1a4863)', () => {
  test('QA-AUTO: after picking a customer the error disappears and the invoice is created #1a4863 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    const s = stamp();
    const title = `QA-AUTO inv-cust #1a4863 ${s}`;
    let invoiceUrl: string | null = null;
    try {
      await openNewInvoiceForm(page);

      // Шаг 1: без клиента — ошибка
      await page.getByRole('button', { name: 'Create Invoice' }).click();
      await expect(customerAlert(page)).toBeVisible();

      // Шаг 2: выбрать клиента — красный текст пропадает
      await pickCustomer(page, CLIENT);
      await expect(customerAlert(page)).toHaveCount(0);
      await expect(page.getByText(CLIENT, { exact: true }).first()).toBeVisible();

      // Шаг 3: имя и позиция (Add Item сохраняет черновик)
      await invoiceNameRow(page).getByRole('button', { name: 'Add name', exact: true }).click();
      const nameInput = invoiceNameRow(page).getByRole('textbox');
      await nameInput.fill(title);
      await nameInput.press('Enter');
      await expect(invoiceNameRow(page).getByRole('button', { name: title })).toBeVisible();
      await addManualItem(page, { name: `QA-AUTO inv-cust-line ${s}`, price: '1' });
      invoiceUrl = page.url();

      // Шаг 4: Create Invoice — счёт создан
      await page.getByRole('button', { name: 'Create Invoice' }).click();
      await expect(page.getByRole('button', { name: 'Create Invoice' })).toHaveCount(0, { timeout: 20_000 });
      await expect(customerAlert(page)).toHaveCount(0);
      await expect.poll(() => invoiceNumber(page), { message: 'номер созданного счёта' }).toMatch(/^INV-\d+$/);
      invoiceUrl = page.url();
    } finally {
      await removeDocumentAt(page, invoiceUrl, title);
    }
  });
});
